<script lang="ts">
 import {meetingConflicts} from './meeting-conflicts';
 import {eventDate} from './calendar';
 import TeamsMeeting from './TeamsMeeting.svelte';
 import MeetingComposer from './MeetingComposer.svelte';
 import MeetingEditor from './MeetingEditor.svelte';
 import {canManageMeeting} from './meeting-edit';
 import MeetingResponse from './MeetingResponse.svelte';
 import {onMount,onDestroy} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {openUrl} from '@tauri-apps/plugin-opener';
 import {CalendarDays,ChevronLeft,ChevronRight,RefreshCw,X,Clock,MapPin,Users} from 'lucide-svelte';
 import {calendarRange,calendarAnchor,validCalendarDay,localDate,eventWhen,eventDay,responseLabel,attendeeResponseLabel,calendarAttendeeLabel,calendarLink,type CalendarEvent} from './calendar';
 let {initialEvent=null,onNavigationHandled=()=>{},ownId,isLive,sidebarOpen,detailsOpen,onDetailsAvailable,onOpenDetails,onCloseDetails,onSignIn}:{initialEvent?:CalendarEvent|null;onNavigationHandled?:()=>void;ownId:string;isLive:boolean;sidebarOpen:boolean;detailsOpen:boolean;onDetailsAvailable:(available:boolean)=>void;onOpenDetails:()=>void;onCloseDetails:()=>void;onSignIn:()=>void}=$props();
 let day=$state(localDate(new Date())),days=$state(7),rows=$state<CalendarEvent[]>([]),selected=$state<CalendarEvent|null>(null),next=$state<string|null>(null),busy=$state(false),error=$state(''),permitted=$state(false),checking=$state(true);
 let managing=$state<{id:string;mode:'edit'|'cancel'}|null>(null);
 let composing=$state(false),canCreate=$state(false),creationNotice=$state('');
 let alive=true,serial=0;
 let responseRefresh=$state(0);
 let pendingEvent:CalendarEvent|null=null;
 async function openTarget(){if(!pendingEvent)return;const target=pendingEvent;const result=await invoke<{event:CalendarEvent}>('calendar_event',{eventId:target.id,messageId:null});if(!alive)return;selected=result.event;day=calendarAnchor(result.event,day);pendingEvent=null;onOpenDetails();}
 $effect(()=>onDetailsAvailable(composing||!managing&&!!selected));
 onDestroy(()=>{alive=false;serial++;onDetailsAvailable(false);});
 onMount(()=>{void (async()=>{try{if(isLive){permitted=await invoke<boolean>('calendar_permission');canCreate=await invoke<boolean>('calendar_response_permission');}if(alive&&permitted){if(initialEvent){pendingEvent=initialEvent;onNavigationHandled();await openTarget();}await load();}}catch(e){if(alive)error=String(e);}finally{if(alive)checking=false;}})();});
 async function load(more=false){const request=++serial;busy=true;error='';try{await openTarget();if(!alive)return;if(!validCalendarDay(day))day=localDate(new Date());const range=calendarRange(day,days);const page=await invoke<{value:CalendarEvent[];next:string|null}>('calendar_page',{...range,next:more?next:null});if(!alive||request!==serial)return;rows=[...new Map([...(more?rows:[]),...page.value].map(e=>[e.id,e])).values()].sort((a,b)=>a.start.dateTime.localeCompare(b.start.dateTime));next=page.next;responseRefresh++;if(selected)selected=rows.find(e=>e.id===selected?.id)??selected;}catch(e){if(alive&&request===serial)error=String(e);}finally{if(alive&&request===serial)busy=false;}}
 function navigate(offset:number){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+offset);day=localDate(d);selected=null;rows=[];next=null;void load();}
 const rooms=$derived((selected?.attendees??[]).filter(attendee=>attendee.type==='resource'));
 const people=$derived((selected?.attendees??[]).filter(attendee=>attendee.type!=='resource'));
 const outlook=$derived(calendarLink(selected?.webLink));
</script>
<div class="calendar-workspace">
 {#if sidebarOpen}<aside class="date-panel"><div class="eyebrow">YOUR TIME. YOUR PACE.</div><h1>Calendar</h1><p>A little room for your day.</p><button disabled={!canCreate||!!managing} onclick={()=>{composing=true;onOpenDetails();}}>New meeting</button><label for="calendar-day">Starting date</label><input id="calendar-day" type="date" bind:value={day} disabled={busy||!permitted||!!managing} onchange={()=>{selected=null;rows=[];next=null;if(!day)day=localDate(new Date());void load();}}/><div class="range-options" aria-label="Calendar range">{#each [1,7,30] as count}<button class:chosen={days===count} disabled={busy||!permitted||!!managing} onclick={()=>{days=count;selected=null;rows=[];next=null;void load();}}>{count===1?'Day':count===7?'Week':'30 days'}</button>{/each}</div><button class="today" disabled={busy||!permitted||!!managing} onclick={()=>{day=localDate(new Date());navigate(0);}}>Today</button><div class="quiet-note">Your calendar, at your pace.<br/>Opening an event does not send a response.</div></aside>{/if}
 {#if managing}{#key managing.id+managing.mode}<MeetingEditor {ownId} eventId={managing.id} mode={managing.mode} onClose={()=>managing=null} onDone={result=>{managing=null;if(result.status==='updated'&&result.event){selected=result.event;day=calendarAnchor(result.event,day);creationNotice='Meeting updated. Attendee updates submitted; changed rooms await acceptance.';}else{selected=null;creationNotice='Cancellation submitted. Calendar and attendee updates may take a moment; no repeat will be sent.';}void load();}}/>{/key}{:else if composing}<MeetingComposer events={rows} {ownId} {detailsOpen} {onOpenDetails} {onCloseDetails} onClose={()=>composing=false} onCreated={(event,warning,submittedDay)=>{composing=false;selected=event;day=calendarAnchor(event,day,submittedDay);creationNotice=event.attendees?.some(a=>a.type==='resource')?'Meeting created. Invitations submitted; room booking awaits its response.':'Meeting created. Invitations submitted.';if(warning)creationNotice+=' '+warning;onOpenDetails();void load();}}/>{:else}<section class="agenda"><header><div><div class="eyebrow">ROOM TO FOCUS</div><h2>{new Date(day+'T12:00:00').toLocaleDateString([],{month:'long',year:'numeric'})}</h2></div><div class="navigation"><button aria-label="Previous calendar range" disabled={busy||!permitted||!!managing} onclick={()=>navigate(-days)}><ChevronLeft size={18}/></button><button aria-label="Next calendar range" disabled={busy||!permitted||!!managing} onclick={()=>navigate(days)}><ChevronRight size={18}/></button><button aria-label="Refresh calendar" disabled={busy||!permitted||!!managing} onclick={()=>load()}><RefreshCw size={18}/></button></div></header>
 <div class="agenda-scroll">{#if creationNotice}<p role="status">{creationNotice}</p>{/if}{#if error}<p class="error" role="alert">{error}</p><button onclick={()=>load()} disabled={busy||!permitted||!!managing}>Try again</button>{/if}
 {#if !isLive}<div class="empty"><CalendarDays size={48}/><h2>Your time, together.</h2><p>Sign in to view your calendar.</p><button onclick={onSignIn}>Sign in to Microsoft 365</button></div>{:else if checking}<p role="status">Connecting your calendar…</p>{:else if !permitted}<div class="empty"><CalendarDays size={48}/><h2>Connect your calendar</h2><p>Calendar needs Calendars.Read consent and a fresh sign-in. Chats and Mail remain available.</p></div>{:else}
 <p class="coverage">{day} · {days} {days===1?'day':'days'} · {rows.length} events loaded{next?' · more available':''}</p>
 {#each rows as event,i (event.id)}{#if i===0||eventDay(rows[i-1])!==eventDay(event)}<h3 class="day-heading">{eventDay(event)}</h3>{/if}<button class="event" class:chosen={selected?.id===event.id} class:cancelled={event.isCancelled} onclick={()=>{selected=event;onOpenDetails();}}><span class="event-time"><Clock size={14}/>{eventWhen(event)}</span><strong>{event.subject||'Untitled event'}</strong><span>{event.location?.displayName||event.organizer?.emailAddress?.name||'Calendar event'}</span><small>{responseLabel(event)}</small>{#if meetingConflicts(rows,eventDate(event.start)?.getTime()??NaN,eventDate(event.end)?.getTime()??NaN,event.id).length&&!event.isCancelled&&event.showAs!=='free'}<small>Overlaps another event</small>{/if}</button>{/each}
 {#if !rows.length&&!busy&&!error}<div class="empty"><CalendarDays size={44}/><h2>A little breathing room.</h2><p>No events in this date range.</p></div>{/if}{#if busy}<p role="status">Loading events…</p>{/if}{#if next}<button disabled={busy} onclick={()=>load(true)}>Load more events</button>{/if}{/if}</div></section>
 {/if}
 {#if !composing&&!managing&&detailsOpen&&selected}<aside class="event-details"><header><div><div class="eyebrow">EVENT DETAILS</div><h2>{selected.subject||'Untitled event'}</h2></div><button aria-label="Close event details" onclick={onCloseDetails}><X size={18}/></button></header><div class="detail-scroll"><TeamsMeeting event={selected}/>{#if ['seriesMaster','occurrence','exception'].includes(selected.type??'')}<p class="coverage">Recurring meeting. Manage the series in Outlook.</p>{/if}{#if canCreate&&canManageMeeting(selected)}<div class="organizer-actions"><button onclick={()=>{if(selected)managing={id:selected.id,mode:'edit'};}}>Edit meeting</button><button onclick={()=>{if(selected)managing={id:selected.id,mode:'cancel'};}}>Cancel meeting</button></div>{/if}{#if rooms.length}<section class="room-booking" aria-label="Room booking"><h3><MapPin size={17}/>Room booking</h3>{#each rooms as room}<div class="room-status" class:declined={room.status?.response==='declined'}><strong class="room-name">{room.emailAddress?.name||room.emailAddress?.address||'Room'}</strong><strong class="room-outcome">{room.status?.response==='declined'?'Room declined':room.status?.response==='accepted'?'Room accepted':!room.status?.response||['none','notResponded'].includes(room.status.response)?'Requested — awaiting room response':attendeeResponseLabel(room.status.response)}</strong>{#if room.status?.response==='declined'}<p>This room is not booked for this meeting.</p>{/if}</div>{/each}</section>{/if}{#key selected.id}<MeetingResponse {ownId} refreshKey={responseRefresh} eventId={selected.id} onUpdated={event=>{selected=event;rows=rows.map(row=>row.id===event.id?event:row);}}/>{/key}<h3><Clock size={16}/>When</h3><p>{eventDay(selected)}<br/>{eventWhen(selected)}</p><small>Timed events shown in {Intl.DateTimeFormat().resolvedOptions().timeZone}. All-day events keep their calendar date.</small><h3><MapPin size={16}/>Where</h3><p>{selected.location?.displayName||'No location provided'}</p><h3>Organizer</h3><p>{selected.organizer?.emailAddress?.name}<br/>{selected.organizer?.emailAddress?.address}</p>{#if selected.bodyPreview}<h3>About this event</h3><p class="description">{selected.bodyPreview}</p><small>Description preview</small>{/if}<h3><Users size={16}/>Attendees · {people.length}</h3>{#each people as attendee}<div class="attendee"><strong>{attendee.emailAddress?.name||attendee.emailAddress?.address||'Attendee'}</strong><small>{calendarAttendeeLabel(selected,attendee)}</small></div>{/each}{#if outlook}<button class="outlook" onclick={()=>{if(outlook)void openUrl(outlook).catch(()=>error='Outlook could not be opened.');}}>Open in Outlook ↗</button>{/if}</div></aside>{/if}
</div>
<style>
.organizer-actions{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px}.organizer-actions button{font-size:12px;color:var(--accent)}

.room-booking{margin:0 0 20px}.detail-scroll .room-booking h3{margin:0 0 12px;font-size:13px;color:var(--text-secondary)}.room-status{padding:16px;border:1px solid var(--border-strong);border-radius:10px;margin-top:10px;background:var(--surface-raised);overflow-wrap:anywhere}.room-name{display:block;font-size:14px;line-height:1.5}.room-outcome{display:block;font-size:16px;line-height:1.5;margin-top:8px}.room-status.declined{background:var(--error-surface);border-color:var(--error-border);border-left-width:4px}.room-status.declined .room-outcome{color:var(--error)}.detail-scroll .room-status p{margin:8px 0 0;font-size:12px;color:var(--text-primary)}

.calendar-workspace{display:flex;flex:1;height:100%;min-height:0;min-width:0;color:var(--text-primary)}button,input{font:inherit;color:inherit}button{cursor:pointer;border:1px solid var(--border);background:var(--surface-panel);border-radius:9px;padding:10px 14px}button:disabled{opacity:.45;cursor:default}button:hover:not(:disabled){border-color:var(--accent)}.eyebrow{color:var(--accent);font-size:10px;letter-spacing:2px;font-weight:700}.date-panel{width:280px;flex:none;padding:32px 24px;background:var(--surface-panel);border-right:1px solid var(--border);display:flex;flex-direction:column;gap:18px}.date-panel h1{font-size:30px;margin:0}.date-panel p,.quiet-note,small,.coverage{color:var(--text-secondary);line-height:1.7}.date-panel label{font-size:12px;margin-top:24px}.date-panel input{width:100%;box-sizing:border-box;padding:12px;border:1px solid var(--border-strong);border-radius:9px;background:var(--surface-raised)}.range-options{display:flex;gap:6px}.range-options button{flex:1;padding:10px 5px}.chosen{border-color:var(--accent)!important;background:var(--accent-soft)!important}.quiet-note{margin-top:auto;font-size:11px}.agenda{flex:1;min-width:0;display:flex;flex-direction:column}.agenda>header,.event-details>header{padding:28px;display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid var(--border);background:var(--surface-panel)}h2{margin:10px 0 0;font-size:23px}.navigation{display:flex;gap:7px}.navigation button{display:grid;place-items:center;padding:10px}.agenda-scroll,.detail-scroll{flex:1;overflow:auto;min-height:0;padding:26px}.coverage{font-size:11px;margin:0 0 28px}.day-heading{font-size:12px;letter-spacing:1px;color:var(--text-secondary);margin:25px 0 12px}.event{width:100%;text-align:left;display:grid;gap:9px;padding:20px 24px;margin-bottom:12px;border-left:3px solid var(--accent);background:var(--surface-panel)}.event strong{font-size:17px}.event>span:not(.event-time){font-size:12px;color:var(--text-secondary)}.event-time{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--accent)}.event small{font-size:11px}.cancelled strong{text-decoration:line-through}.empty{padding:60px 20px;text-align:center;color:var(--text-secondary)}.empty :global(svg){color:var(--accent)}.empty p{line-height:1.8}.event-details{width:350px;max-width:40%;flex:none;display:flex;flex-direction:column;background:var(--surface-panel);border-left:1px solid var(--border)}.event-details h2{font-size:19px;line-height:1.5}.detail-scroll h3{display:flex;gap:9px;align-items:center;font-size:12px;margin-top:28px}.detail-scroll p{line-height:1.8;font-size:13px;overflow-wrap:anywhere}.detail-scroll small{font-size:11px}.description{white-space:pre-wrap}.attendee{display:grid;gap:5px;padding:12px 0;border-bottom:1px solid var(--border);font-size:12px}.outlook{margin-top:24px;color:var(--accent)}.error{color:var(--danger-text,#e88d7d);line-height:1.7}@media(max-width:1000px){.date-panel{width:210px;padding:24px 16px}.event-details{width:290px}}button:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
</style>
